body_compound_inlined.sql:
CREATE FUNCTION f (instr VARCHAR(100)) RETURNS VARCHAR(100)
DETERMINISTIC NO EXTERNAL ACTION CONTAINS SQL
BEGIN ATOMIC
  DECLARE revstr VARCHAR(100) DEFAULT '';
  DECLARE len INT;
  IF instr IS NULL THEN RETURN NULL; END IF;
  SET len = LENGTH(instr);
  WHILE len > 0 DO
    SET revstr = SUBSTR(instr, len, 1) CONCAT revstr;
    SET len = len - 1;
  END WHILE;
  RETURN revstr;
END;

